    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "When a given industry —water and electricity are two well-known examples — carries high infrastructural start-up costs and other barriers that\n\ndiscourage competition, ______ of just one or two suppliers per municipality. Such industries are known as natural monopolies.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
