    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Star actress Kiki Omeili, who has appeared in 47 Nollywood films, is one of numerous luminaries to be pictured in Nigerian portraitist Iké Udé s ’\nexhibition Nollywood Portraits. ______ referred to Nollywood — ’\n Nigeria s $3 billion film industry — “\n as ’\n Africa s vivid mirror par excellence, ” honors its\n\nlegacy with his vivid classical portraits of Omeili and her peers.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
