    "id": "aaa1907f",
    "section": "reading-writing",
    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "To serve local families during the Great Depression, innovative New York City librarian Pura Belpr é offered storytelling in both English and\nSpanish, an uncommon ______ celebrated el Día de los Tres Reyes Magos, an important community holiday; and put on puppet shows dramatizing\n\nPuerto Rican folktales.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "practice, at the time",
      "practice at the time;",
      "practice, at the time,",
      "practice at the time,"
    ],
    "correctAnswer": 1,
    "explanation": "Choice B is the best answer. The convention being tested is the punctuation of elements in a complex series. It’s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after \"time\" is conventionally used to separate the first item (\"offered…time\") and the second (\"celebrated…holiday\") in the series of activities that librarian Pura Belpr é offered. Moreover, the semicolon after \"time\" matches the semicolon used later to separate the second item (\"celebrated...holiday\") and the third (\"and...folktales\") in the series. Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Furthermore, a comma isn’t needed between the noun \"practice\" and the prepositional phrase \"at the time\" because the prepositional phrase is essential to the full meaning of the phrase \"an uncommon practice at the time.\" Choice C is incorrect because a comma after \"time\" doesn’t match the semicolon used later to separate the second (\"celebrated...holiday\") and third (\"and...folktales\") items in the series. Furthermore, a comma isn’t needed between the noun \"practice\" and the prepositional phrase \"at the time\" because the prepositional phrase is essential to the full meaning of the phrase \"an uncommon practice at the time.\" Choice D is incorrect because a comma after \"time\" doesn’t match the semicolon used later to separate the second (\"celebrated...holiday\") and third (\"and...folktales\") items in the series.",
    "textbookRef": {
      "textbookId": "sat-reading-writing-mastery",
      "page": 3,
      "highlightedText": "Standard English Conventions: Sentence Boundaries & Clause Coordination"
    },
    "createdAt": "2026-08-15T00:00:00Z",
