    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "Photosynthesis, the mechanism by which plants use sunlight to turn carbon dioxide and water into ______ is fueled in part by an enzyme called\n\nPhotosystem II that harvests energy-giving electrons from water molecules.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
