    "questionText": "Human-made (synthetic) fibers used in clothes and many other consumer products are more durable than most natural plant ______ the\n\nmanufacture of synthetic fibers requires toxic chemical solvents that can pollute air and water.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
