    "questionText": "Entomologists Yash Sondhi and Samuel Fabian have tried to explain why moths fly erratically around light sources at night. Knowing that flying\n\ninsects keep their backs pointed toward sunlight during the day, ______\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
