    "questionText": "The Herfindahl-Hirschman Index (HHI), a commonly used measure of competition between companies in a particular market, ranges from a\n\nscore of zero to 10,000 points. Compared with that of a highly concentrated market — that is, a market controlled by very few companies —______\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
