    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "According to the traditional RYB (red-yellow-blue) color model, yellow is a complementary color to purple. However, yellow ______ considered\n\ncomplementary to blue in modern color theory.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
