    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Atoms in a synchrotron, a type of circular particle accelerator, travel faster and faster until they ______ a desired energy level, at which point they\n\nare diverted to collide with a target, smashing the atoms.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
