    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Emperor penguins don’t waddle out of the ocean. They launch themselves at such a high speed that they travel up to two meters before landing.\n\nHow ______ A layer of microbubbles on their plumage reduces friction as the penguins speed to the surface.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
