    "correctAnswer": 1,
    "explanation": "Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb “to expand” is correctly used to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do. Choice A is incorrect because it results in an ungrammatical sentence. The finite verb “is expanding” can’t be used in this way to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do. Choice C is incorrect because it results in an ungrammatical sentence. The finite verb “has expanded” can’t be used in this way to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb “expands” can’t be used in this way to form a subordinate clause that indicates what the National Oceanic and Atmospheric Administration seeks to do.",
