    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "During a 2022 expedition led by research zoologist Andrea Quattrini, scientists discovered a new species of black coral off the coast of Puerto\n\nRico. Like other black corals, the newly discovered species, which they named Aphanipathes puertoricoensis, has coiled branching structures that\n\n______ it survive in the deep sea.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
