    "section": "reading-writing",
    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "’\nIn addition to advocating for South America s independence in two political treatises, the Cartagena Manifesto and the Letter from Jamaica,\n\nSimón Bolívar personally led armies against the Spanish, liberating three South American territories — New Granada (present-day Colombia and\n\nPanama), Venezuela, and Quito (present-day ______ from colonial rule.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "Ecuador,)",
      "Ecuador)",
      "Ecuador),",
      "Ecuador) —"
    ],
    "correctAnswer": 3,
    "explanation": "Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The dash after “ Ecuador ” and the closing parenthesis pairs with the dash after “ ” territories “ to separate the supplementary element ( New … ” Ecuador ) from the rest of the sentence. The supplementary element specifies the three South American territories that Simón Bolívar liberated, and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence. Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. ’ Furthermore, punctuation isn t needed between “ Ecuador ” and the closing parenthesis. Choice B is incorrect because it fails to use appropriate ’ punctuation to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a comma can t be paired with a dash to separate the supplementary element from the rest of the sentence.",
