    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "Julia Alvarez’s 1994 novel In the Time of the Butterflies, a fictionalized account of the lives of the Mirabal ______ can serve as a starting point for\n\nthose wanting to explore how the rule of dictator Rafael Trujillo has been represented in Dominican American literature.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
