    "section": "reading-writing",
    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "“What stories like this do for us is make the world just a smidge bigger,” writes Stephen Graham Jones in the foreword to Never Whistle at Night:\n\nAn Indigenous Dark Fiction Anthology. For Jones, dark fiction does more than entertain readers: ______ horror tropes to challenge familiar ways of\n\nknowing, blurring the “borders of the real.”\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "one uses",
      "we use",
      "they use",
      "it uses"
    ],
    "correctAnswer": 3,
    "explanation": "Choice D is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun “it” agrees in number with the singular antecedent “dark fiction” and clearly indicates that dark fiction uses horror tropes to challenge familiar ways of knowing. Choice A is incorrect because the singular pronoun “one” is ambiguous in this context; the resulting sentence leaves unclear who or what uses horror tropes to challenge familiar ways of knowing. Choice B is incorrect because the first person plural pronoun “we” isn’t conventional as a substitute for “dark fiction.” It suggests that the readers, rather than dark fiction, use horror tropes to challenge familiar ways of knowing. Choice C is incorrect because the plural pronoun “they” doesn’t agree in number with the singular antecedent “dark fiction.”",
