    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "In her book The Woman Warrior: Memoirs of a Girlhood Among Ghosts, author Maxine Hong Kingston examines themes ______ childhood,\n\nwomanhood, and Chinese American identity by intertwining autobiography and mythology.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
