    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "Gathering accurate data on water flow in the United States is challenging because of the country’s millions of miles of ______ the volume and\n\nspeed of water at any given location can vary drastically over time.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
