    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "The term “ ”\n retroflex derives from Latin and means “\n bent back,” an apt descriptor for the branch of consonants — retroflex consonants —\npronounced with the tongue curling up and back in the mouth. In many languages, including English, these consonants are ______ in some\n\ndialects of Mandarin, however, four such consonants ( ch, “ ”“ ”“ ”\n sh, zh, and “”\n r ) are relatively common.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
