    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "Archaeologists have estimated that the pre-Columbian Native American city of Cahokia, located across the Mississippi River from modern-day\n\nSt. Louis, Missouri, had as many as 20,000 inhabitants in the year 1150 ______ it one of the largest cities in North America at the time.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
