    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Eighteen letters written by Louisa May Alcott, author of the popular novel Little Women (1868), can be found at the New York Historical Society.\n\n______ letters demonstrate Alcott’s keen business sense in her interactions with publishers.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
