    "questionText": "Cy Twombly, a US painter and sculptor, created many large-scale abstract works, such as his 10-painting series Fifty Days at Iliam. In these works,\n\nTwombly’s artistic style is exemplified by his use of graffiti-like ______ often incorporate words or phrases from poetry and mythology.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
