    "questionText": "Tortoises can be found in many works of literature. For example, in Tom Stoppard’s 1993 play Arcadia\n , there is a tortoise that ______ by two\n\nnames (Plautus and Lightning) and appears in both of the play’s parallel timelines. As a character, the tortoise symbolizes the connection\n\nbetween the past and present.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
