    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "The city of Pompeii, which was buried in ash following the eruption of Mount Vesuvius in 79 CE, continues to be studied by archaeologists.\n\nUnfortunately, as ______ attest, archaeological excavations have disrupted ash deposits at the site, causing valuable information about the\n\neruption to be lost.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
