    "difficulty": "expert",
    "questionText": "’\nWoven from recycled yarn and hand tufted using a carpet weaving technique passed down by the artist s Turkish grandmother, ______ so lush and\n\ntactilely inviting that you are tempted to reach out and touch them.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
