    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "In paleontology, the term “Elvis taxon” gets applied to a newly identified living species that was once presumed to be extinct. Like an Elvis\n\nimpersonator who might bear a striking resemblance to the late musical icon Elvis Presley himself, an Elvis taxon is not the real thing, ______ is a\n\nmisidentified look-alike.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
