    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Smaller than poppy seeds, tardigrades are tiny, but they are tough. These minuscule animals can survive for thirty years without food or water,\n\nand ______ can withstand extreme temperatures as low as minus 328 degrees and as high as 304 degrees Fahrenheit.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
