    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Along with carbon dioxide concentration and temperature, light intensity affects the chemical reaction rate of ______ as light intensity increases,\n\nso does the rate at which the reactants (water and carbon dioxide) are converted into their products (glucose and oxygen).\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
