    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "To illustrate Albert Einstein’s special theory of relativity, picture two jugglers: one juggling on a steadily moving parade float, the other juggling\n\nwhile standing still on a sidewalk. The laws of physics are identical for both ______ motion relative to each other. But what, Einstein wondered,\n\nabout the speed of light?\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
