    "questionText": "The life spans of rockfish vary greatly by species. For instance, the colorful calico rockfish (Sebastes dallii) can survive for a little over a ______\n\nthe rougheye rockfish (Sebastes aleutianus) boasts a maximum life span of about two centuries.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
