    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Most of the ice found on Earth is ice Ih, distinguished by a crystalline structure in which molecules form a hexagonal pattern. Amorphous ice, on\n\nthe other hand, constitutes most of the ice in the ultrafrigid environment of outer space. Defined by a disorganized molecular structure, ______\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
