    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "In his groundbreaking book Bengali Harlem and the Lost Histories of South Asian America, Vivek Bald uses newspaper articles, census records,\n\nships’ logs, and memoirs to tell the ______ who made New York City their home in the early twentieth century.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
