    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "When writing The Other Black Girl (2021), novelist Zakiya Dalila Harris drew on her own experiences working at a publishing office. The award-\n\n ’\nwinning book is Harris s first novel, but her writing ______ honored before. At the age of twelve, she entered a contest to have a story published in\n\nAmerican Girl magazine — and won.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
