    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "’\nThe forty-seven geothermal springs of Arkansas Hot Springs National Park are sourced via a process known as natural groundwater recharge, in\n\nwhich rainwater percolates downward through the earth —\n in this case, the porous rocks of the hills around Hot ______ collect in a subterranean\n\nbasin.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
