    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "According to Naomi Nakayama of the University of Edinburgh, the reason seeds from a dying dandelion appear to float in the air while ______ is\n\nthat their porous plumes enhance drag, allowing the seeds to stay airborne long enough for the wind to disperse them throughout the\n\nsurrounding area.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
