    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Lê Lương Minh became the thirteenth secretary-general of the Association of Southeast Asian Nations (ASEAN) in January 2013, making ______\nthe first time the organization would appoint a Vietnamese leader.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
