    "questionText": "For thousands of years, humans have used domesticated goats (Capra hircus) to clear land of unwanted vegetation. When it comes to their diets,\n\ngoats are notoriously ______ they will devour all kinds of shrubs and weeds, leaving virtually no part of any plant unconsumed.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
