    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Occupying a significant part of modern-day Nigeria, the Kingdom of Benin was one of the major powers in West Africa between the thirteenth\n\nand nineteenth centuries. It ______ ruled by Oba Ewuare I from 1440 to 1473.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
