    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Mia Heavener’s 2019 novel Under Nushagak Bluff, which takes place in a mid-twentieth-century rural Alaskan fishing ______ the story of three\n\nYup’ik women who grapple with the rise of commercial fisheries and other changes affecting their community.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
