    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Quantum particles of light— photons —provide an unhackable means of transmitting encryption keys over networks, as attempts to observe\n\nparticles in quantum states will invariably alter the particles ______ dismantle any information they transmit.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
