    "section": "reading-writing",
    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "Lucía Michel of the University of Chile observed that alkaline soils contain an insoluble form of iron that blueberry plants cannot absorb, thus\n\ninhibiting blueberry growth. If these plants were grown in alkaline soil alongside grasses that aid in iron solubilization, ______ Michel was\n\ndetermined to find out.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
