    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "Featuring jagged peaks of black ink surrounded by hazy swirls of blue and green paint, Zhang Daqian’s 1983 painting Panorama of Mount Lu is\n\n ü shanshui, a type of Chinese landscape painting ______ by the use of blue and green hues to depict ethereal,\ninspired by the tradition of qingl\n\notherworldly landscapes.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
