    "id": "d46ac7e7",
    "section": "reading-writing",
    "domain": "standard-english-conventions",
    "skill": "Boundaries",
    "difficulty": "beginner",
    "questionText": "A second-generation Japanese American, Wataru Misaka ______ in World War II (1941-45) and won two amateur national basketball\n\nchampionships at the University of Utah when he joined the New York Knicks for the 1947-48 season, becoming the first non-white basketball\n\nplayer in the US’s top professional league.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "already served",
      "was already serving",
      "already serves",
      "had already served"
    ],
    "correctAnswer": 3,
    "explanation": "Choice D is the best answer. Misaka served in World War II before he joined the New York Knicks in 1947. To show that a past occurrence took place before another past occurrence, we need to use “had” + the past tense form of the verb. This is called the past perfect tense. Choice A is incorrect. Misaka served in World War II before he joined the Knicks. Both events are in the past, but his service in World War II happened earlier, so we need a verb that makes it clear that his service (and the two national championships) had ended by the time he joined the Knicks. Choice B is incorrect. “Was already serving” forms the continuous past tense, which we use when we’re showing a past action that was ongoing. Misaka served in World War II before he joined the Knicks. Both events are in the past, but they’re not happening at the same time, so we shouldn’t use the continuous past tense here. Choice C is incorrect. Misaka served in World War II in the past, so we shouldn’t use the present tense “serves.”",
    "textbookRef": {
      "textbookId": "sat-reading-writing-mastery",
      "page": 3,
      "highlightedText": "Standard English Conventions: Sentence Boundaries & Clause Coordination"
    },
