    "questionText": "The city of Amsterdam partnered with consultants to develop Public Eye — an ethical AI-powered crowd-monitoring ______ video streamed from\n\n ’\ncameras in heavily touristed areas, the AI algorithm determines crowd sizes without, in the interest of protecting individuals privacy, retaining the\n\nfootage.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
