    "questionText": "Mary Madden of Ohio ______ a fierce advocate of women’s voting rights in the late 1800s. The dedication of Madden and her fellow activists was\n\nrewarded in 1920, when the Nineteenth Amendment to the US Constitution guaranteed American women the right to vote.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
