    "difficulty": "beginner",
    "questionText": "Photographer Ansel Adams’s landscape portraits are iconic pieces of American art. However, many of the ______ of landscapes were intended\n\nnot as art but as marketing; a concessions company at Yosemite National Park had hired Adams to take pictures of the park for restaurant\n\nmenus and brochures.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
