    "questionText": "“Praise Song for the Day,” Elizabeth Alexander’s 2009 inaugural poem, asserts that “We cross dirt roads and highways…to see what’s on the other\n\nside.” Alexander’s use of “we” ______ Americans’ collective efforts and shared desire to seek new opportunity.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
