    "difficulty": "beginner",
    "questionText": "At 1,280 meters, the Golden Gate Bridge in the United States is one of the longest suspension bridges in the ______ the Tsing Ma Bridge in China,\n\nat 1,377 meters, is even longer.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
