    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Latin America is known to have dozens, if not hundreds, of popular dance forms. Only five of these dances are included in international ballroom\n\ndance ______ rumba, samba, cha-cha-cha, paso doble, and jive — the last of which is grouped with the other Latin dances despite not having Latin\n\nroots.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
