    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Stomata, tiny pore structures in a leaf that absorb gases needed for plant growth, open when guard cells surrounding each pore swell with water.\n\nIn a pivotal 2007 article, plant cell ______ showed that lipid molecules called phosphatidylinositol phosphates are responsible for signaling guard\n\ncells to open stomata.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
