    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Nuhād al- Ḥaddād, known as Fairuz, was one of the most beloved Lebanese singers of the twentieth century. Her broad singing repertoire —which\n\nincluded traditional forms, such as the Arabic qasida and maqam, alongside modern pop and jazz styles—lent Fairuz a timeless, cross-\ngenerational appeal, ______ her the moniker “\n the soul of Lebanon. ”\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
