    "questionText": "In 1994, almost 200 years after the death of Wang Zhenyi, the International Astronomical ______ the contributions of the barrier-breaking 18th-\n\ncentury astronomer and author of “Dispute of the Procession of the Equinoxes,” naming a crater on Venus after her.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
