    "questionText": "Botanists recognize over fifty different species of sunflower. One species, the silverleaf sunflower, ______ both an early-flowering ecotype that\n\ntends to grow in coastal areas and a late-flowering ecotype that grows inland.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
