    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "The 2022 Nobel Prize in Chemistry was awarded to three pioneers in the field of click chemistry: two-time Nobel laureate Barry Sharpless, who\n\ncoined the term “click chemistry” in 1998; Carolyn Bertozzi, founder of the Bertozzi Group at ______ and Morten Meldal, a professor at the\n\nUniversity of Copenhagen in Denmark.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
    "options": [
      "Stanford",
      "Stanford,",
      "Stanford:",
      "Stanford;"
    ],
    "correctAnswer": 3,
    "explanation": "Choice D is the best answer. This choice correctly uses a semicolon to punctuate a complex list (which is made up of items that have commas in them). Choice A is incorrect. This is a complex list, indicated by the semicolon between \"1998\" and \"Carolyn Bertozzi.\" What comes after the blank is a separate list item, so punctuation is needed after \"Stanford.\" Choice B is incorrect. This is a complex list, indicated by the semicolon between \"1998\" and \"Carolyn Bertozzi.\" The items in this list have internal punctuation in the form of commas and must therefore be separated by semicolons to avoid confusion. Choice C is incorrect. This is a complex list, indicated by the semicolon between \"1998\" and \"Carolyn Bertozzi.\" Colons aren’t used to separate items in a list.",
    "textbookRef": {
      "textbookId": "sat-reading-writing-mastery",
      "page": 3,
      "highlightedText": "Standard English Conventions: Sentence Boundaries & Clause Coordination"
    },
