    "correctAnswer": 3,
    "explanation": "Choice D is the best answer. Faure redesigned the battery in 1881, and the original battery was invented “fifteen years earlier.” Notice that this is the only choice in the past tense. To indicate that a past occurrence took place before another past occurrence, we need to use “had” + the past tense form of the verb. This is called the “past perfect” tense. é invented the original battery in the past, so we shouldn t use the present tense is Choice A is incorrect. This choice creates a tense error. Plant ’ “ inventing. Choice B is incorrect. This choice creates a tense error. Planté invented the original battery in the past, so we shouldn t use the future ” ’ é invented the original battery in the past, so we shouldn t use the tense “will invent.” Choice C is incorrect. This choice creates a tense error. Plant ’ present tense “invents.”",
    "textbookRef": {
      "textbookId": "sat-reading-writing-mastery",
      "page": 3,
      "highlightedText": "Standard English Conventions: Sentence Boundaries & Clause Coordination"
    },
