    "skill": "Boundaries",
    "difficulty": "expert",
    "questionText": "Instead of sleeping on soft pillows, ancient Egyptians slept on hard, elevated headrests, their design ______ airflow, protection from insects, and\n\nhairstyle maintenance over comfort.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
