    "skill": "Boundaries",
    "difficulty": "intermediate",
    "questionText": "While constructing the Limyra Bridge, ancient Roman builders relied on temporary wooden beams to support the stone and brick structure.\n\nThese temporary supports, a construction system known as ______ were removed when the bridge was completed.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
