    "questionText": "A pioneer in the field of taphonomy (the study of how organic remains become fossils), ______ may be just as prevalent in the fossil record as\n\nthose of thick-shelled organisms.\n\nWhich choice completes the text so that it conforms to the conventions of Standard English?",
